const items = $input.all();

const clean = (value) => {
  if (value === null || value === undefined) return '';
  if (Array.isArray(value)) return value.map(clean).filter(Boolean).join(', ');
  return String(value).trim();
};

const pick = (source, names) => {
  for (const name of names) {
    const value = source[name];
    if (clean(value)) return value;
  }
  return '';
};

const docIdFromUrl = (url) => {
  const value = clean(url);
  const match = value.match(/\/document\/d\/([^/]+)/);
  return match ? match[1] : '';
};

const attendanceFromReason = (reason) => {
  const text = clean(reason);
  const match = text.match(/attendance_status\s*=\s*([a-z_]+)/i);
  return match ? match[1].toLowerCase() : '';
};

const attendanceReasonFromDecision = (reason) => {
  const text = clean(reason);
  const match = text.match(/attendance_status\s*=\s*[a-z_]+\s*:\s*([^|]+)/i);
  return match ? clean(match[1]) : '';
};

return items.map((item, index) => {
  const raw = item.json || {};
  const fields = raw.fields && typeof raw.fields === 'object' ? raw.fields : raw;
  const recordId = clean(raw.id || raw.recordId || fields.id || fields.recordId);
  const transcriptDoc = clean(pick(fields, ['Meeting Transcript Link', 'Transcript Doc', 'meeting_transcript_link', 'Meeting Transcript']));
  const transcriptDocId = clean(pick(fields, ['Transcript Google Doc ID', 'Google Doc ID'])) || docIdFromUrl(transcriptDoc);
  const meetingId = clean(pick(fields, ['Meeting ID', 'meeting_id']));
  const repEmail = clean(pick(fields, ['Rep Email', 'Sales Rep Email', 'rep_email']));
  const repName = clean(pick(fields, ['Rep Name', 'Sales Rep', 'rep_name'])) || (repEmail ? repEmail.split('@')[0].replace(/[._-]+/g, ' ') : '');
  const processingStatus = clean(pick(fields, ['Processing Status', 'processing_status']));
  const aiDecisionReason = clean(pick(fields, ['AI Decision Reason', 'ai_decision_reason']));
  const upstreamAttendanceStatus = clean(pick(fields, ['Attendance Status', 'attendance_status'])) || attendanceFromReason(aiDecisionReason);
  const upstreamAttendanceReason = clean(pick(fields, ['Attendance Reason', 'attendance_reason'])) || attendanceReasonFromDecision(aiDecisionReason);
  const scorecardKey = clean(pick(fields, ['Automation Key', 'Scorecard Key', 'scorecard_key'])) || (recordId ? `airtable:${recordId}` : [meetingId, transcriptDocId].filter(Boolean).join(':'));

  return {
    json: {
      ...fields,
      'Date/Time': clean(pick(fields, ['Meeting Start Date', 'Date/Time', 'call_date', 'Ingested At'])),
      'Meeting ID': meetingId,
      'Sales Rep Email': repEmail,
      'Sales Rep': repName,
      'Client Name': clean(pick(fields, ['Client Name', 'client_name'])),
      'Title Of Meeting': clean(pick(fields, ['Meeting Title', 'Title Of Meeting', 'meeting_title'])),
      'Meeting Duration': clean(pick(fields, ['Meeting Duration', 'Duration Minutes', 'Duration', 'durationMinutes', 'minutes'])),
      'Transcript Doc': transcriptDoc,
      'Transcript Google Doc ID': transcriptDocId,
      'Zoom Url': clean(pick(fields, ['Meeting Link', 'Zoom Url', 'meeting_link'])),
      'Show Name': clean(pick(fields, ['Show Name', 'show_name'])),
      'Scorecard Key': scorecardKey,
      'Source Airtable Record ID': recordId,
      'Source Airtable Created Time': clean(raw.createdTime || fields.createdTime || fields['Created Time']),
      'Source Airtable Ingested At': clean(pick(fields, ['Ingested At', 'source_airtable_ingested_at'])),
      'Source Airtable Processing Status': processingStatus,
      'Upstream Attendance Status': upstreamAttendanceStatus,
      'Upstream Attendance Reason': upstreamAttendanceReason
    },
    pairedItem: { item: index }
  };
}).filter((item) => {
  return item.json['Source Airtable Processing Status'] === 'Processed' && item.json['Transcript Doc'];
});

function failureDecision(message, checkpoints=[], attempt=0, now=Date.now()) {
  const raw=String(message || 'Unknown coaching failure');
  const msg=(raw.split(/\|\s*Error:\s*/).pop() || raw).split(/\|\s*(?:Transcript chars|Meeting ID|Source Record|Execution ID):/)[0].trim();
  const httpCode=msg.match(/(?:^|\bHTTP\s+|\bstatus(?:Code)?\s*[:=]\s*)(401|403|429|500|502|503|504|524|529)\b/i)?.[1];
  // Prefer the original typed cause. Never search transcript/meeting numbers for HTTP codes.
  if (['401','403'].includes(httpCode) || /\brefusal\b|invalid source|source mismatch|ownership changed|uncertain|partial delivery|report write detected/i.test(msg)) return {kind:'safety_hold',retryable:false};
  const incomplete=checkpoints.filter(c=>['running','failed'].includes(c.status)).sort((a,b)=>Date.parse(b.updated_at)-Date.parse(a.updated_at))[0];
  if (/Error executing workflow|checkpoint deferred|task request timed out/i.test(msg) && incomplete) {
    if (incomplete.status==='running') return {kind:'checkpoint_incomplete',stage:incomplete.stage,retryable:true,retryAt:Math.max(now+60000,Date.parse(incomplete.lease_until)||now+300000)};
    const cause=failureDecision(incomplete.last_error,[],attempt,now);
    return {...cause,stage:incomplete.stage,retryAt:Math.max(now+60000,Date.parse(incomplete.next_attempt_at)||now+300000)};
  }
  if (/invalid coaching contract|Missing strength|draft remains invalid|Invalid transcript evidence|Invalid coaching audit|Incomplete improvement audit|Conflicting improvement audit|Incomplete factual audit|Invalid audited outcome/i.test(msg)) return {kind:'content_contract',retryable:attempt<2};
  if (['429','500','502','503','504','524','529'].includes(httpCode) || /timeout|timed out|aborted|overload|rate.?limit|temporar|ECONNRESET|ETIMEDOUT|EAI_AGAIN|fetch failed|socket|connection.*closed|empty response|JSON parse|invalid structured|checkpoint (deferred|unavailable)/i.test(msg)) return {kind:'transient',retryable:true};
  return {kind:'unknown',retryable:false};
}
function queueFailure(sourceId, executionId, message, attempt=0, now=Date.now(), checkpoints=[]) {
  if (!/^rec[A-Za-z0-9]+$/.test(sourceId)) throw Error("Invalid recovery source");
  const decision=failureDecision(message,checkpoints,attempt,now);
  const eligible=decision.retryable;
  const delay=attempt>=3?86400000:[300000,900000,3600000][Math.max(0,attempt)];
  return {source_id:sourceId,execution_id:String(executionId),updated_at:new Date(now).toISOString(),report_id:"",
    status:eligible?"queued":"needs_review",attempts:attempt,
    message:(eligible?`retry_at=${new Date(Math.max(now+delay,decision.retryAt||0)).toISOString()} | `:"")+`kind=${decision.kind}${decision.stage?' stage='+decision.stage:''} | `+String(message).slice(0,850)};
}
const recovery=$('MM Recovery Entry').isExecuted;
const attempt=recovery?Number($('MM Recovery Entry').first().json.recovery_attempt||1):0;
const failure=$('Set: agent_failed').item.json;
const source=String($('If').item.json['Source Airtable Record ID']||'');
const diagnostics=$json.source_id===source&&Array.isArray($json.checkpoints)?$json.checkpoints:[];
let message=String(failure.error_details||failure.error?.message||failure.message||'Coaching failed');
if($json.error && /Error executing workflow/.test(message))message+=' | checkpoint unavailable';
return {json:queueFailure(source,$execution.id,message,attempt,Date.now(),diagnostics),pairedItem:{item:0}};

let body=$json;
if (body?.body!==undefined) body=body.body;
if (typeof body==='string') {try{body=JSON.parse(body)}catch{body={}}}
if(body?._readableState?.buffer){try{body=JSON.parse(body._readableState.buffer.map(b=>String.fromCharCode(...(b.data||[]))).join(''))}catch{body={}}}
const report_id=String($('Create a record').item.json.id);
const verified=body?.ok===true&&String(body.airtable_record_id||'')===report_id&&Boolean(body.id);
return {json:{source_id:String($('If').item.json['Source Airtable Record ID']||''),execution_id:String($execution.id),updated_at:new Date().toISOString(),report_id,status:verified?'delivered':'needs_review',attempts:$('MM Recovery Entry').isExecuted?Number($('MM Recovery Entry').first().json.recovery_attempt||1):0,message:verified?'Dashboard confirmed report '+String(body.id)+'; source report and document created.':'Dashboard response did not confirm the matching report; inspect before retrying delivery.'}};

let source='';try{source=$('Loop Over Items').item.json['Source Airtable Record ID']||'';}catch{}
const message=String($json.error?.message||$json.error||$json.message||'Source outcome receipt failed').replace(/Bearer\s+\S+/gi,'Bearer [redacted]').replace(/https?:\/\/\S+/g,'[url]').slice(0,800);
console.error('Magic Mike accounting failure',String($execution.id),source,message);
return {json:{event_key:'accounting:'+$execution.id+':'+source,workflow_id:$workflow.id,execution_id:String($execution.id),call_key:source,stage:'source_accounting',status:'needs_review',message,occurred_at:new Date().toISOString()},pairedItem:{item:0}};

function coveragePlan(scan, receipts) {
  if(scan.status!=='ready' || !scan.token || !Array.isArray(scan.source_ids)) return null;
  const bySource=new Map(receipts.map(row=>[row.source_id,row]));
  const reported=new Set(scan.reported||[]);
  const delivered=new Set(scan.delivered_ids||[]);
  const missing=scan.source_ids.filter(id=>!delivered.has(id)&&bySource.get(id)?.status!=='excluded');
  // Queued/processing are unresolved, not success. Alert only when stale, or held for review.
  const attention=missing.filter(id=>{
    const row=bySource.get(id);
    return !row || !['queued','processing'].includes(row.status) || !row.updated_at || Date.now()-Date.parse(row.updated_at)>86400000;
  });
  return {token:scan.token,missing_ids:missing,notify:attention.filter(id=>!reported.has(id)),checked:scan.checked};
}
const plan=coveragePlan($('Read Coverage Page').first().json,$input.all().map(x=>x.json));return plan?[{json:plan,pairedItem:{item:0}}]:[];
